begin;
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end$$;
create function pg_temp.reject(q text,want text) returns void language plpgsql as $$begin begin execute q;exception when others then if sqlerrm=want or sqlstate=want then return;end if;raise;end;raise exception 'Expected rejection: %',want;end$$;
insert into auth.users(id,email,email_confirmed_at) values
('a0000000-0000-4000-8000-000000000001','admin-test@example.test',now()),
('a0000000-0000-4000-8000-000000000002','professional-a@example.test',now()),
('a0000000-0000-4000-8000-000000000003','professional-b@example.test',now()),
('a0000000-0000-4000-8000-000000000004','professional-c@example.test',now());
update public.professional_profiles set full_name='Synthetic admin test' where id::text like 'a0000000%';
insert into private.platform_admins(user_id) values('a0000000-0000-4000-8000-000000000001');
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select pg_temp.assert_true(not (public.my_access()->>'is_admin')::boolean,'normal account not admin');
select pg_temp.assert_true(not (public.my_access()->'access'->>'allowed')::boolean,'new account denied by default');
select pg_temp.reject($q$select public.admin_api('overview')$q$,'42501');
select pg_temp.reject($q$select public.admin_api('professional','{"professional_id":"a0000000-0000-4000-8000-000000000003"}')$q$,'42501');
select pg_temp.reject('select * from private.plans','42501');
select pg_temp.reject('select * from private.professional_access','42501');
select pg_temp.reject($q$insert into private.platform_admins(user_id) values(auth.uid())$q$,'42501');
reset role;
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select pg_temp.assert_true((public.my_access()->>'is_admin')::boolean,'admin identified');
select pg_temp.assert_true(public.admin_api('overview')->>'registered' is not null,'admin authorized');
select pg_temp.assert_true(jsonb_array_length(public.admin_api('catalog')->'entitlements')=16,'catalog');
select pg_temp.assert_true(jsonb_array_length(public.admin_api('professionals','{"search":"professional-a@"}')->'items')=1,'search by account email');
-- All writes go through the actual browser RPC with a real authenticated role.
select public.admin_api('save_plan',(public.admin_api('catalog')->'plans'->0)-'id'-'updated_at'||'{"code":"test_admin_plan","name":"Test plan","monthly_price":99,"annual_price":999,"active":true}');
select public.admin_api('save_plan',(select p from jsonb_array_elements(public.admin_api('catalog')->'plans') p where p->>'code'='test_admin_plan')||'{"name":"Updated plan","active":false}');
select pg_temp.assert_true((select p->>'name'='Updated plan' and p->>'active'='false' from jsonb_array_elements(public.admin_api('catalog')->'plans') p where p->>'code'='test_admin_plan'),'edit and deactivate plan');
select public.admin_api('save_plan',(select p from jsonb_array_elements(public.admin_api('catalog')->'plans') p where p->>'code'='test_admin_plan')||'{"active":true}');
select public.admin_api('set_access',jsonb_build_object('professional_id','a0000000-0000-4000-8000-000000000002','plan_id',(select p->>'id' from jsonb_array_elements(public.admin_api('catalog')->'plans') p where p->>'code'='test_admin_plan'),'status','active','starts_at',now()-interval '1 day','reason','test'));
select public.admin_api('set_access',jsonb_build_object('professional_id','a0000000-0000-4000-8000-000000000003','plan_id',(select p->>'id' from jsonb_array_elements(public.admin_api('catalog')->'plans') p where p->>'code'='beta'),'status','trial','starts_at',now()-interval '1 day','ends_at',now()+interval '90 days','reason','test'));
select pg_temp.assert_true((public.admin_api('professional','{"professional_id":"a0000000-0000-4000-8000-000000000002"}')->'access'->'values'->>'diet_workshop')::boolean,'base plan');
select public.admin_api('set_override',jsonb_build_object('professional_id','a0000000-0000-4000-8000-000000000002','entitlement_key','diet_workshop','value',false,'starts_at',now()-interval '1 day','ends_at',now()+interval '1 day','reason','override'));
select pg_temp.assert_true(not (public.admin_api('professional','{"professional_id":"a0000000-0000-4000-8000-000000000002"}')->'access'->'values'->>'diet_workshop')::boolean,'override wins');
select public.admin_api('set_override',jsonb_build_object('professional_id','a0000000-0000-4000-8000-000000000002','entitlement_key','diet_workshop','value',true,'starts_at',now()-interval '2 days','ends_at',now()-interval '1 day','reason','expired'));
select pg_temp.assert_true(not (public.admin_api('professional','{"professional_id":"a0000000-0000-4000-8000-000000000002"}')->'access'->'values'->>'diet_workshop')::boolean,'expired override ignored');
select public.admin_api('grant_access',jsonb_build_object('professional_id','a0000000-0000-4000-8000-000000000002','plan_id',(select p->>'id' from jsonb_array_elements(public.admin_api('catalog')->'plans') p where p->>'code'='beta'),'starts_at',now()-interval '1 hour','ends_at',now()+interval '90 days','reason','courtesy'));
select pg_temp.assert_true(public.admin_api('professional','{"professional_id":"a0000000-0000-4000-8000-000000000002"}')->'access'->>'status'='trial','courtesy temporal');
select pg_temp.assert_true(public.admin_api('professional','{"professional_id":"a0000000-0000-4000-8000-000000000002"}')->'access'->'values'->>'ai.monthly_credits'='0','beta zero included');
select public.admin_api('adjust_credits','{"professional_id":"a0000000-0000-4000-8000-000000000002","amount":300,"operation_key":"a1000000-0000-4000-8000-000000000001","reason":"Courtesy"}');
select public.admin_api('adjust_credits','{"professional_id":"a0000000-0000-4000-8000-000000000002","amount":300,"operation_key":"a1000000-0000-4000-8000-000000000001","reason":"Retry"}');
select pg_temp.assert_true(public.admin_api('professional','{"professional_id":"a0000000-0000-4000-8000-000000000002"}')->'ai'->>'available'='300.000','atomic idempotent credit grant');
select pg_temp.assert_true((public.admin_api('professional','{"professional_id":"a0000000-0000-4000-8000-000000000003"}')->'ai'->>'available')::numeric=0,'B untouched');
select pg_temp.reject($q$select public.admin_api('adjust_credits','{"professional_id":"a0000000-0000-4000-8000-000000000002","amount":-301,"operation_key":"a1000000-0000-4000-8000-000000000002","reason":"overdraw"}')$q$,'insufficient_unreserved_credits');
select public.admin_api('adjust_credits','{"professional_id":"a0000000-0000-4000-8000-000000000002","amount":-50,"operation_key":"a1000000-0000-4000-8000-000000000003","reason":"Correction"}');
select public.admin_api('save_code',jsonb_build_object('code','TESTBETA5','name','Pilot test','plan_id',(select p->>'id' from jsonb_array_elements(public.admin_api('catalog')->'plans') p where p->>'code'='beta'),'duration_days',90,'max_redemptions',1,'initial_ai_credits',25,'starts_at',now()-interval '1 day','expires_at',now()+interval '1 day','active',true));
select pg_temp.assert_true(position('code_hash' in public.admin_api('codes')::text)=0,'no code hash in UI');
reset role;
select pg_temp.assert_true((select sum(purchased_delta)=250 and count(*)=2 from private.ai_credit_ledger where professional_id='a0000000-0000-4000-8000-000000000002'),'ledger totals');
select pg_temp.assert_true((select count(*)=2 from private.admin_audit where target_professional='a0000000-0000-4000-8000-000000000002' and action='adjust_credits'),'one audit per adjustment');
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000004',true);
set local role authenticated;
select public.redeem_access_code('testbeta5');
select pg_temp.assert_true(public.my_access()->'access'->>'status'='trial','valid code assigns trial');
select pg_temp.reject($q$select public.redeem_access_code('TESTBETA5')$q$,'code_already_redeemed');
select pg_temp.reject($q$select public.redeem_access_code('WRONGCODE')$q$,'code_unavailable');
reset role;
select pg_temp.assert_true((select purchased_credits=25 from private.ai_accounts where professional_id='a0000000-0000-4000-8000-000000000004'),'initial credits ledger');
insert into auth.users(id,email,email_confirmed_at) values('a0000000-0000-4000-8000-000000000005','professional-d@example.test',now());
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000005',true);
set local role authenticated;
select pg_temp.reject($q$select public.redeem_access_code('TESTBETA5')$q$,'code_unavailable');
reset role;
update private.access_codes set max_redemptions=5,active=false where name='Pilot test';
set local role authenticated;
select pg_temp.reject($q$select public.redeem_access_code('TESTBETA5')$q$,'code_unavailable');
reset role;
update private.access_codes set active=true,starts_at=now()-interval '2 days',expires_at=now()-interval '1 day' where name='Pilot test';
set local role authenticated;
select pg_temp.reject($q$select public.redeem_access_code('TESTBETA5')$q$,'code_unavailable');
reset role;
-- A standalone courtesy expires/revokes back to unassigned, never indefinite.
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select public.admin_api('grant_access',jsonb_build_object('professional_id','a0000000-0000-4000-8000-000000000005','plan_id',(select p->>'id' from jsonb_array_elements(public.admin_api('catalog')->'plans') p where p->>'code'='beta'),'starts_at',now()-interval '1 hour','ends_at',now()+interval '1 hour'));
select pg_temp.assert_true(public.admin_api('professional','{"professional_id":"a0000000-0000-4000-8000-000000000005"}')->'access'->>'status'='trial','standalone courtesy');
select public.admin_api('suspend','{"professional_id":"a0000000-0000-4000-8000-000000000005","reason":"pause trial"}');
select pg_temp.assert_true(public.admin_api('professional','{"professional_id":"a0000000-0000-4000-8000-000000000005"}')->'access'->>'status'='suspended','suspend standalone courtesy');
select public.admin_api('reactivate','{"professional_id":"a0000000-0000-4000-8000-000000000005","reason":"resume trial"}');
select pg_temp.assert_true(public.admin_api('professional','{"professional_id":"a0000000-0000-4000-8000-000000000005"}')->'access'->>'status'='trial','resume existing courtesy');
select public.admin_api('revoke_grant',jsonb_build_object('professional_id','a0000000-0000-4000-8000-000000000005','id',public.admin_api('professional','{"professional_id":"a0000000-0000-4000-8000-000000000005"}')->'grants'->0->>'id','reason','end trial'));
select pg_temp.assert_true(not (public.admin_api('professional','{"professional_id":"a0000000-0000-4000-8000-000000000005"}')->'access'->>'allowed')::boolean,'revocation removes standalone access');
reset role;
update private.access_grants set ends_at=now()-interval '1 minute' where professional_id='a0000000-0000-4000-8000-000000000002';
select pg_temp.assert_true(private.resolve_effective_entitlements('a0000000-0000-4000-8000-000000000002')->>'plan_name'='Updated plan','expired courtesy restores base');
update private.access_grants set ends_at=now()+interval '1 day' where professional_id='a0000000-0000-4000-8000-000000000002';
-- Suspension retains rows; both RLS and definer writes enforce the decision.
insert into public.patients(id,professional_id,full_name) values('b0000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000002','LOCAL SYNTHETIC');
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select public.admin_api('suspend','{"professional_id":"a0000000-0000-4000-8000-000000000002","reason":"test"}');
reset role;
select pg_temp.assert_true((select count(*)=1 from public.patients where professional_id='a0000000-0000-4000-8000-000000000002'),'suspension preserves patients');
select pg_temp.reject($q$update public.patients set full_name='No' where id='b0000000-0000-4000-8000-000000000001'$q$,'42501');
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select pg_temp.assert_true(not (public.my_access()->'access'->>'allowed')::boolean,'suspension wins over courtesy');
select pg_temp.assert_true((select count(*)=0 from public.patients),'suspended reads denied');
select pg_temp.reject($q$select public.require_entitlement('patients')$q$,'42501');
reset role;
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select public.admin_api('reactivate','{"professional_id":"a0000000-0000-4000-8000-000000000002","reason":"test"}');
select public.admin_api('set_override',jsonb_build_object('professional_id','a0000000-0000-4000-8000-000000000002','entitlement_key','patients.limit','value',1,'starts_at',now()-interval '1 hour','reason','quota'));
reset role;
select pg_temp.reject($q$insert into public.patients(professional_id,full_name) values('a0000000-0000-4000-8000-000000000002','LIMIT TEST')$q$,'patients_limit_reached');
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000003',true);
set local role authenticated;
select pg_temp.assert_true((select count(*)=0 from public.patients),'A/B clinical isolation retained');
reset role;
select pg_temp.assert_true(not has_function_privilege('anon','public.admin_api(text,jsonb)','EXECUTE'),'anon RPC revoked');
select pg_temp.assert_true(not has_function_privilege('authenticated','private.resolve_effective_entitlements(uuid)','EXECUTE'),'arbitrary owner resolver revoked');
select pg_temp.assert_true(not has_table_privilege('authenticated','private.ai_accounts','UPDATE'),'no direct balance writes');
-- Included credits can be withdrawn only while current, without consuming reservations.
insert into private.ai_accounts(professional_id,included_credits,purchased_credits,reserved_included,reserved_purchased,billing_period_start,billing_period_end)
values('a0000000-0000-4000-8000-000000000003',100,20,30,10,now()-interval '1 day',now()+interval '1 day');
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select public.admin_api('adjust_credits','{"professional_id":"a0000000-0000-4000-8000-000000000003","amount":-80,"operation_key":"a1000000-0000-4000-8000-000000000011","reason":"Included withdrawal"}');
select pg_temp.reject($q$select public.admin_api('adjust_credits','{"professional_id":"a0000000-0000-4000-8000-000000000003","amount":-1,"operation_key":"a1000000-0000-4000-8000-000000000012","reason":"Reserved funds"}')$q$,'insufficient_unreserved_credits');
reset role;
select pg_temp.assert_true((select purchased_credits=10 and included_credits=30 and reserved_purchased=10 and reserved_included=30 from private.ai_accounts where professional_id='a0000000-0000-4000-8000-000000000003'),'reserved balances untouched');
select pg_temp.assert_true((select purchased_delta=-10 and included_delta=-70 from private.ai_credit_ledger where operation_key='a1000000-0000-4000-8000-000000000011'),'withdrawal allocated in ledger');
update private.ai_accounts set included_credits=100,billing_period_start=now()-interval '2 days',billing_period_end=now()-interval '1 day' where professional_id='a0000000-0000-4000-8000-000000000003';
set local role authenticated;
select pg_temp.reject($q$select public.admin_api('adjust_credits','{"professional_id":"a0000000-0000-4000-8000-000000000003","amount":-1,"operation_key":"a1000000-0000-4000-8000-000000000013","reason":"Expired funds"}')$q$,'insufficient_unreserved_credits');
reset role;
rollback;
select 'PASS: ADMIN-1 authorization, plan catalog, overrides, courtesy, ledger, codes, suspension, quotas and isolation. OPENAI CALLS = 0';
